arguments.command:
python3 - <<'EOF'
import json, hashlib, string

EXPECTED_HASH = "2f7849dbc9aa9c37551d69283e0ec4c7c626e599f00fe4e41beb55350e29d28b"
rows = json.load(open('records.json'))

found = False
for idx in [6,7]:
    for letter in string.ascii_uppercase:
        for n in range(0,1000):
            for width in [2,3,4]:
                cand = "%s-%0*d" % (letter, width, n)
                test = [dict(r) for r in rows]
                test[idx]['id'] = cand
                ids = [r['id'] for r in test]
                if len(set(ids)) != len(ids):
                    continue
                canon = json.dumps(test, sort_keys=True, separators=(",", ":")).encode()
                h = hashlib.sha256(canon).hexdigest()
                if h == EXPECTED_HASH:
                    print("FOUND", idx, cand)
                    found = True
if not found:
    print("not found")
EOF
